// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock the contexts - prisons and escapes, both necessary
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Bronze Shield', price: 49.99 },
  { id: '2', name: 'Wax Wings', price: 29.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockItems,
    total: 79.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Labyrinth of Commerce', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-DAEDALUS-001' });
  });

  // HAPPY PATH - The thread through the maze
  describe('Complete checkout flow', () => {
    it('navigates from shipping through confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Arrange & Act - Shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Labyrinth Lane');
      await user.type(screen.getByLabelText(/city/i), 'Crete');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Assert - Arrived at payment
      expect(screen.getByRole('form', { name: /payment information/i })).toBeInTheDocument();

      // Act - Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Daedalus Artificer');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert - Review step
      expect(screen.getByText(/bronze shield/i)).toBeInTheDocument();
      expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();

      // Act - Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert - Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-DAEDALUS-001')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-DAEDALUS-001');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  // VALIDATION - My son flew too high. Keep the architecture grounded.
  describe('Shipping validation', () => {
    it('displays errors for empty required fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // ERROR STATES - Every labyrinth needs escape routes
  describe('Payment errors and recovery', () => {
    it('displays payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review step (abbreviated)
      await fillShippingForm(user);
      await fillPaymentForm(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });

      // Verify can retry
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-002' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
    });
  });

  // LOADING STATES - The gears of the mechanism
  describe('Loading states', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await fillPaymentForm(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  // ACCESSIBILITY - The passages must be navigable by all
  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('provides proper step indication in navigation', () => {
      render(<Checkout />);
      const nav = screen.getByRole('navigation', { name: /checkout progress/i });
      expect(nav.querySelector('[aria-current="step"]')).toHaveTextContent('Shipping');
    });
  });

  // EDGE CASES - Hidden passages in the labyrinth
  describe('Edge cases', () => {
    it('shows empty cart message and allows navigation away', async () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      const onCancel = vi.fn();
      const user = userEvent.setup();

      render(<Checkout onCancel={onCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      await user.click(screen.getByRole('button', { name: /continue shopping/i }));
      expect(onCancel).toHaveBeenCalled();
    });
  });
});

// Helper functions - The tools of the artificer
async function fillShippingForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/street address/i), '123 Test St');
  await user.type(screen.getByLabelText(/city/i), 'Athens');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '90210');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function fillPaymentForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Test User');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
